package com.example.orderprocessing.controller;
import com.example.orderprocessing.dto.OrderRequest; import com.example.orderprocessing.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class DashboardController {private final OrderService orders; private final ProductService products; public DashboardController(OrderService orders,ProductService products){this.orders=orders;this.products=products;} @GetMapping("/dashboard/summary") public Object summary(){return orders.summary();} @GetMapping("/dashboard/metrics") public Object metrics(){var inventory=products.all();var orderList=orders.all();double sales=orderList.stream().filter(o->o.getStatus().name().equals("COMPLETED")||o.getStatus().name().equals("DELIVERED")||o.getStatus().name().equals("SHIPPED")).mapToDouble(o->o.getProduct().getPrice()*o.getQuantity()).sum();return Map.of("totalProducts",inventory.size(),"inventoryValue",inventory.stream().mapToDouble(p->p.getPrice()*p.getAvailableInventory()).sum(),"lowStockProducts",inventory.stream().filter(p->p.isLowStock()).count(),"outOfStockProducts",inventory.stream().filter(p->p.isOutOfStock()).count(),"totalSales",sales,"averageOrderValue",orderList.isEmpty()?0:sales/orderList.size());} @GetMapping("/dashboard/orders") public Object dashboardOrders(){return orders.all().stream().map(orders::orderView).toList();} @GetMapping("/dashboard/inventory") public Object inventory(){return products.all();} @GetMapping("/inventory/movements") public Object movements(@RequestParam(required=false) Long productId){return products.movements(productId);} @PostMapping("/simulation/orders") public Object simulate(@Valid @RequestBody OrderRequest request,@RequestParam(defaultValue="20") int numberOfOrders){return orders.simulate(request,numberOfOrders);} @GetMapping("/health") public Object health(){return Map.of("status","UP","workers","5 core / 10 max","locking","PESSIMISTIC_WRITE");} }
